args.script:
(() => {
  const xmlText = document.documentElement ? document.documentElement.textContent : '';
  let doc = document;
  if (!doc.querySelector || !doc.querySelector('item')) {
    doc = new DOMParser().parseFromString(xmlText, 'application/xml');
  }
  const items = Array.from(doc.querySelectorAll('item')).slice(0, 5).map(item => ({
    title: item.querySelector('title')?.textContent?.trim(),
    link: item.querySelector('link')?.textContent?.trim(),
    pubDate: item.querySelector('pubDate')?.textContent?.trim()
  }));
  return {url: location.href, title: document.title, items, textSample: xmlText.slice(0, 500)};
})()
